<?php ob_start(); ?><h1>Signatures</h1><form><select class="input" name="enabled"><option value="">Any status</option><option value="1" <?= ($_GET['enabled']??'')==='1'?'selected':'' ?>>enabled</option><option value="0" <?= ($_GET['enabled']??'')==='0'?'selected':'' ?>>disabled</option></select> <input class="input" name="risk" placeholder="risk" value="<?= e($_GET['risk']??'') ?>"> <input class="input" name="type" placeholder="type" value="<?= e($_GET['type']??'') ?>"> <input class="input" name="source" placeholder="source" value="<?= e($_GET['source']??'') ?>"> <button class="btn">Filter</button> <a class="btn" href="/signatures/create">Create manual signature</a></form><table><tr><th>ID</th><th>Name</th><th>Risk</th><th>Type</th><th>Pattern</th><th>Source</th><th>Enabled</th><th>Actions</th></tr><?php foreach($signatures as $s): ?><tr><td><?= e($s['id']) ?></td><td><a href="/signatures/<?= e($s['id']) ?>"><?= e($s['name']) ?></a></td><td><span class="badge <?= e($s['risk']) ?>"><?= e($s['risk']) ?></span></td><td><?= e($s['type']) ?></td><td><?= e($s['pattern_type']) ?></td><td><?= e($s['source']) ?></td><td><?= e($s['enabled']) ?></td><td><form method="post" action="/signatures/toggle" style="display:inline"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn small"><?= $s['enabled']?'Disable':'Enable' ?></button></form> <form method="post" action="/signatures/duplicate" style="display:inline"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn small">Duplicate</button></form> <form method="post" action="/signatures/delete" style="display:inline" onsubmit="return confirm('Delete signature?')"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn danger small">Delete</button></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>